module benchmark.maintenance;

fn access_stamp(clock: I64, idle: I64, multiplier: I64) -> I64 !{} {
    let limit = 16777215;
    let age = idle * multiplier / 1000;
    let absolute = clock - age;
    if absolute < 0 { return (absolute + limit); }
    return absolute;
}

fn loaded_stamp(clock: I64, seconds: I64) -> I64 !{} {
    return access_stamp(clock, seconds, 1000);
}

fn module_stamp(clock: I64, millis: I64) -> I64 !{} {
    return access_stamp(clock, millis, 1);
}

pub fn main() -> I64 !{} { var total = 0; var i = 0; while i < 2000000 { total += access_stamp(i % 16777216, i % 10001, 1000); i += 1; } return total; }

