module benchmark.maintenance;

fn scale_channel(level: I64, fraction: I64, fixed_mode: Bool) -> I64 !{} {
    let product = (level * (fraction + (if fixed_mode { 1 } else { 0 })));
    return product / 256;
}

fn interpolate_byte(start: I64, end: I64, fraction: I64, fixed_mode: Bool) -> I64 !{} {
    if end > start { return start + scale_channel(end - start, fraction, fixed_mode); }
    return start - scale_channel(start - end, fraction, fixed_mode);
}

fn map_byte(value: I64, low: I64, high: I64, fixed_mode: Bool) -> I64 !{} {
    return low + scale_channel(value, high - low, fixed_mode);
}

pub fn main() -> I64 !{} { var total = 0; var i = 0; while i < 2000000 { total += scale_channel(i % 256, (i / 256) % 256, i % 2 == 0); i += 1; } return total; }

