module benchmark.maintenance;

fn period_end(year: I64, elapsed: I64) -> I64 !{} {
    if elapsed < 6048000 { return 6048000; }
    if elapsed < 26784000 { return 26784000; }
    return (if year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) { 366 } else { 365 }) * 86400;
}

fn zone_bounds_end(year: I64, elapsed: I64, january_unix: I64) -> I64 !{} {
    return january_unix + period_end(year, elapsed);
}

fn date_rechecks(year: I64, elapsed: I64, offset: I64) -> I64 !{} {
    let start = if elapsed >= 26784000 { 26784000 } else { if elapsed >= 6048000 { 6048000 } else { 0 } };
    let utc = elapsed - offset;
    return if offset != 0 && (utc < start || utc >= period_end(year, elapsed)) { 1 } else { 0 };
}

pub fn main() -> I64 !{} { var total = 0; var i = 0; while i < 2000000 { total += period_end(1600 + i % 801, (i * 17) % 31536000); i += 1; } return total; }

