def period_end(year: int, elapsed: int) -> int:
    if elapsed < 6048000:
        return 6048000
    if elapsed < 26784000:
        return 26784000
    return (366 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 365) * 86400

def zone_bounds_end(year: int, elapsed: int, january_unix: int) -> int:
    return january_unix + period_end(year, elapsed)

def date_rechecks(year: int, elapsed: int, offset: int) -> int:
    start = 26784000 if elapsed >= 26784000 else (6048000 if elapsed >= 6048000 else 0)
    utc = elapsed - offset
    return int(offset != 0 and (utc < start or utc >= period_end(year, elapsed)))

def main() -> int:
    total = 0
    i = 0
    while i < 2000000:
        total += period_end(1600 + i % 801, (i * 17) % 31536000)
        i += 1
    return total
print(main())
